IMPLEMENT_TMPDIR="<TMPDIR>"
# Clear the stall from ship-pr-state.sh
awk '/^STALL_TRACKING=/{print "STALL_TRACKING=false"; next}
     /^STALL_STEP=/{print "STALL_STEP="; next}
     /^PHASE=/{print "PHASE=checks"; next}
     {print}' "$IMPLEMENT_TMPDIR/ship-pr-state.sh" > "$IMPLEMENT_TMPDIR/ship-pr-state.sh.tmp" \
  && mv "$IMPLEMENT_TMPDIR/ship-pr-state.sh.tmp" "$IMPLEMENT_TMPDIR/ship-pr-state.sh"
echo "Stall cleared"
git log --oneline -6
